import { useState } from 'react';
import garb from './assets/garb.svg';
import pencil from './assets/pencil.svg';
// TaskList takes tasks and displays them
const TaskList = ({tasks, deleteTask, editTask}) => {

  const [isEditing, setIsEditing] = useState(null);
  const [editedTask, setEditedTask] = useState({ name: "", desc: "" });
  const handleInputChange = (e, field) => {
    setEditedTask((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleEditTask = (id) => {
    setIsEditing(id);
    const taskToEdit = tasks.find((task) => task.id === id);
    if (taskToEdit) {
      setEditedTask({ name: taskToEdit.name, desc: taskToEdit.desc });
    }
  };
    return (
      <div className="taskDisplayContainer w-full space-y-4 max-h-[400px] overflow-y-auto">
        {tasks.map((task, index) => (
          <div
            className="taskDisplay relative py-2 flex flex-col items-center justify-center w-full font-normal border-b border-white last:border-none"
            key={task.id}
          >
            <div className="flex justify-end w-full space-x-2 px-4">
              <img
                className="w-6 h-6 rounded-lg hover:scale-110 transition duration-100 ease-in-out cursor-pointer"
                onClick={() => handleEditTask(task.id)}
                src={pencil}
                alt="edit task"
              />
              <img
                className="w-6 h-6 rounded-lg hover:scale-110 transition duration-100 ease-in-out cursor-pointer"
                onClick={() => deleteTask(task.id)}
                src={garb}
                alt="delete task"
              />
            </div>
            {isEditing === task.id ? (
              <>
                <input
                  className="taskNameInput py-2 w-full text-white text-left text-lg bg-white bg-opacity-0 rounded-lg focus:outline-none focus:bg-none placeholder-white"
                  type="text"
                  placeholder="What're you up to?"
                  value={editedTask.name}
                  onChange={(e) => handleInputChange(e, "name")}
                />
                <input 
                  className="taskwhitespace-normal break-words w-full text-white text-3xl sm:text-2xl font-normal py-2 px-4 text-left"
                  type="text"
                  placeholder="Add a note!"
                  value={editedTask.desc}
                  onChange={(e) => handleInputChange(e, "desc")}
                />
              </>
            ) : (
              <>
                <h1 
                className="whitespace-normal break-words w-full text-white text-3xl sm:text-2xl font-normal py-2 px-4 text-left">
                  {task.name}
                </h1>
                {task.desc && (
                  <p className="whitespace-normal break-words w-full text-white sm:text-lg font-normal py-2 px-4 text-left">
                    {task.desc}
                  </p>
                )}
              </>
            )}
          </div>
        ))}
      </div>
    );
};

export default TaskList;
